rules.expr:
sum by (cluster) (

  count_over_time(
    {app_kubernetes_io_name="cert-manager", cluster!~".*-production"}
    |= "ACME client for issuer not initialised/available" [15m]
  )
) > 3

sum by (cluster) (

  count_over_time(
    {app_kubernetes_io_name="cert-manager", cluster!~".*-production"}
    |= "error presenting challenge" [15m]
  )
) > 1

sum by (cluster) (

  count_over_time(
    {app_kubernetes_io_name="cert-manager", cluster=~".*-production"}
    |= "ACME client for issuer not initialised/available" [15m]
  )
) > 3

sum by (cluster) (

  count_over_time(
    {app_kubernetes_io_name="cert-manager", cluster=~".*-production"}
    |= "error presenting challenge" [15m]
  )
) > 1
